'use client'

import { useState, useEffect } from 'react'
import { getShifts, createShift, updateShift, deleteShift, Shift } from '@/app/api/shifts.api'
import { getSecurityUsers } from '@/app/api/securityUsers.api'
import { getScanPointsByFactory } from '@/app/api/scanPoints.api'

export interface ScanPoint {
  qr_id: string;
  qr_name: string;
  factory_code: string;
}
import { getAllocations, allocateGuards, ShiftAllocation } from '@/app/api/allocations.api'
import { SecurityUser } from '@/app/types/securityUser'
import { useAuthGuard } from '@/app/services/auth.guard'

export default function ShiftsPage() {
  const { authorized } = useAuthGuard()
  const FIXED_CAMPUS = 'KCET01'
  
  // Data State
  const [shifts, setShifts] = useState<Shift[]>([])
  const [guards, setGuards] = useState<SecurityUser[]>([])
  const [qrs, setQrs] = useState<ScanPoint[]>([])
  
  const [allocations, setAllocations] = useState<ShiftAllocation[]>([])
  
  // UI State
  const [activeTab, setActiveTab] = useState<'shifts' | 'allocations'>('allocations')
  const [loading, setLoading] = useState(true)
  
  // Selected state for allocations
  const [selectedShift, setSelectedShift] = useState<string>('')
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().slice(0, 10))
  
  // Form for shift creation
  const [isShiftFormOpen, setIsShiftFormOpen] = useState(false)
  const [editingShift, setEditingShift] = useState<Shift | null>(null)
  const [shiftForm, setShiftForm] = useState({ shift_name: '', start_time: '', end_time: '' })
  
  // Form for allocation
  // Record<qr_id, guard_id>
  const [guardAssignments, setGuardAssignments] = useState<Record<string, string>>({})
  
  const loadData = async () => {
    if (!authorized) return
    setLoading(true)
    try {
      const [shiftsData, usersData, qrsData] = await Promise.all([
        getShifts(),
        getSecurityUsers(),
        getScanPointsByFactory(FIXED_CAMPUS)
      ])
      
      setShifts(shiftsData || [])
      if (shiftsData?.length > 0 && !selectedShift) {
        setSelectedShift(shiftsData[0].shift_id)
      }
      
      const guardsList = (Array.isArray(usersData) ? usersData : []).filter(u => u.role === 'Guard' || !u.role)
      setGuards(guardsList)
      
      // Filter QRs for the fixed campus
      const campusQrs = (Array.isArray(qrsData) ? qrsData : []).filter(q => q.factory_code === FIXED_CAMPUS)
      setQrs(campusQrs)
      
    } catch (error) {
      console.error('Error loading data:', error)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (authorized) loadData()
  }, [authorized])

  // Load allocations when shift/date changes
  useEffect(() => {
    const loadAllocations = async () => {
      if (!selectedShift || !selectedDate) return
      try {
        const allocs = await getAllocations(selectedShift, selectedDate)
        setAllocations(allocs)
        
        // Populate assignment state
        const assignments: Record<string, string> = {}
        allocs.forEach(a => {
          assignments[a.qr_id] = a.guard_id
        })
        setGuardAssignments(assignments)
      } catch (error) {
        console.error('Error loading allocations:', error)
      }
    }
    loadAllocations()
  }, [selectedShift, selectedDate])

  const handleSaveShift = async (e: React.FormEvent) => {
    e.preventDefault()
    try {
      if (editingShift) {
        await updateShift(editingShift.shift_id, shiftForm)
      } else {
        await createShift(shiftForm)
      }
      setIsShiftFormOpen(false)
      loadData()
    } catch (error) {
      console.error('Error saving shift:', error)
      alert('Failed to save shift')
    }
  }

  const handleDeleteShift = async (id: string) => {
    if (!confirm('Delete this shift?')) return
    try {
      await deleteShift(id)
      loadData()
    } catch (error) {
      console.error('Error deleting shift:', error)
      alert('Failed to delete shift')
    }
  }
  
  const handleAssignmentChange = (qrId: string, guardId: string) => {
    setGuardAssignments(prev => {
      const next = { ...prev }
      if (!guardId) {
        delete next[qrId]
      } else {
        next[qrId] = guardId
      }
      return next
    })
  }

  const handleSaveAllocations = async () => {
    if (!selectedShift || !selectedDate) {
      alert('Please select a shift and date')
      return
    }
    
    const allocationsToSave = Object.entries(guardAssignments).map(([qr_id, guard_id]) => ({
      shift_id: selectedShift,
      date: selectedDate,
      guard_id,
      qr_id
    }))
    
    try {
      await allocateGuards(allocationsToSave)
      alert('Allocations saved successfully')
    } catch (error) {
      console.error('Error saving allocations:', error)
      alert('Failed to save allocations')
    }
  }

  if (!authorized) {
    return (
      <div className="p-6 text-white min-h-screen bg-[#07071f] flex items-center justify-center">
        Checking access...
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-slate-50 p-8 font-sans">
      <div className="max-w-7xl mx-auto mb-10">
        <h1 className="text-3xl font-extrabold text-slate-800 tracking-tight">Shift Management</h1>
        <p className="text-slate-500 mt-1 font-medium">Configure shifts and allocate guards to scan points</p>
      </div>

      <div className="max-w-7xl mx-auto mb-6 flex gap-4 border-b border-slate-200">
        <button
          onClick={() => setActiveTab('allocations')}
          className={`pb-4 px-2 font-medium text-sm transition-colors relative ${
            activeTab === 'allocations' ? 'text-indigo-600' : 'text-slate-500 hover:text-slate-700'
          }`}
        >
          Guard Allocations
          {activeTab === 'allocations' && (
            <div className="absolute bottom-0 left-0 w-full h-0.5 bg-indigo-600" />
          )}
        </button>
        <button
          onClick={() => setActiveTab('shifts')}
          className={`pb-4 px-2 font-medium text-sm transition-colors relative ${
            activeTab === 'shifts' ? 'text-indigo-600' : 'text-slate-500 hover:text-slate-700'
          }`}
        >
          Shift Configuration
          {activeTab === 'shifts' && (
            <div className="absolute bottom-0 left-0 w-full h-0.5 bg-indigo-600" />
          )}
        </button>
      </div>

      <div className="max-w-7xl mx-auto">
        {activeTab === 'shifts' && (
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-lg font-semibold text-slate-800">Available Shifts</h2>
              <button
                onClick={() => {
                  setEditingShift(null)
                  setShiftForm({ shift_name: '', start_time: '', end_time: '' })
                  setIsShiftFormOpen(true)
                }}
                className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-indigo-700 transition-colors"
              >
                + Add Shift
              </button>
            </div>
            
            {loading ? (
              <p className="text-slate-500 text-center py-8">Loading shifts...</p>
            ) : shifts.length === 0 ? (
              <div className="text-center py-12 border-2 border-dashed border-slate-200 rounded-xl">
                <p className="text-slate-500 font-medium">No shifts configured yet</p>
                <p className="text-slate-400 text-sm mt-1">Create your first shift to start allocating guards</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {shifts.map(shift => (
                  <div key={shift.shift_id} className="border border-slate-200 rounded-xl p-5 bg-slate-50 hover:border-indigo-200 transition-colors">
                    <div className="flex justify-between items-start mb-4">
                      <h3 className="font-bold text-slate-800 text-lg">{shift.shift_name}</h3>
                      <div className="flex gap-2">
                        <button
                          onClick={() => {
                            setEditingShift(shift)
                            setShiftForm({ shift_name: shift.shift_name, start_time: shift.start_time, end_time: shift.end_time })
                            setIsShiftFormOpen(true)
                          }}
                          className="text-slate-400 hover:text-indigo-600 transition-colors"
                        >
                          ✎
                        </button>
                        <button
                          onClick={() => handleDeleteShift(shift.shift_id)}
                          className="text-slate-400 hover:text-rose-600 transition-colors"
                        >
                          ×
                        </button>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 text-slate-600 text-sm bg-white px-3 py-2 rounded-lg border border-slate-100">
                      <span className="font-mono bg-indigo-50 text-indigo-700 px-2 rounded">{shift.start_time}</span>
                      <span className="text-slate-400">to</span>
                      <span className="font-mono bg-indigo-50 text-indigo-700 px-2 rounded">{shift.end_time}</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'allocations' && (
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
            <div className="flex flex-col md:flex-row gap-4 mb-8">
              <div className="flex-1">
                <label className="block text-sm font-medium text-slate-700 mb-1">Select Shift</label>
                <select
                  value={selectedShift}
                  onChange={(e) => setSelectedShift(e.target.value)}
                  className="w-full border-slate-200 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 shadow-sm"
                >
                  <option value="" disabled>Select a shift</option>
                  {shifts.map(s => (
                    <option key={s.shift_id} value={s.shift_id}>{s.shift_name} ({s.start_time} - {s.end_time})</option>
                  ))}
                </select>
              </div>
              <div className="flex-1">
                <label className="block text-sm font-medium text-slate-700 mb-1">Date</label>
                <input
                  type="date"
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  className="w-full border-slate-200 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 shadow-sm"
                />
              </div>
            </div>

            {loading ? (
              <p className="text-slate-500 text-center py-8">Loading allocations...</p>
            ) : !selectedShift ? (
              <p className="text-slate-500 text-center py-8">Please select a shift to view allocations</p>
            ) : qrs.length === 0 ? (
              <p className="text-slate-500 text-center py-8">No scan points configured for this campus</p>
            ) : (
              <div>
                <div className="mb-4 flex justify-between items-center">
                  <h3 className="text-lg font-medium text-slate-800">Scan Point Assignments</h3>
                  <button
                    onClick={handleSaveAllocations}
                    className="bg-emerald-600 text-white px-5 py-2 rounded-lg text-sm font-medium hover:bg-emerald-700 transition-colors flex items-center gap-2 shadow-sm"
                  >
                    Save Allocations
                  </button>
                </div>
                
                <div className="overflow-hidden border border-slate-200 rounded-lg">
                  <table className="min-w-full divide-y divide-slate-200">
                    <thead className="bg-slate-50">
                      <tr>
                        <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider w-1/2">
                          Scan Point (QR)
                        </th>
                        <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider w-1/2">
                          Assigned Guard
                        </th>
                      </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-slate-200">
                      {qrs.map((qr) => (
                        <tr key={qr.qr_id} className="hover:bg-slate-50">
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="text-sm font-medium text-slate-900">{qr.qr_name}</div>
                            <div className="text-xs text-slate-500">{qr.qr_id}</div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <select
                              value={guardAssignments[qr.qr_id] || ''}
                              onChange={(e) => handleAssignmentChange(qr.qr_id, e.target.value)}
                              className="w-full text-sm border-slate-200 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
                            >
                              <option value="">-- Unassigned --</option>
                              {guards.map(g => (
                                <option key={g.security_id} value={g.security_id}>
                                  {g.security_name} ({g.security_id})
                                </option>
                              ))}
                            </select>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Shift Form Modal */}
      {isShiftFormOpen && (
        <div className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-6 shadow-xl">
            <h2 className="text-xl font-bold mb-5 text-slate-800">
              {editingShift ? 'Edit Shift' : 'Create New Shift'}
            </h2>
            
            <form onSubmit={handleSaveShift} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Shift Name</label>
                <input
                  type="text"
                  required
                  value={shiftForm.shift_name}
                  onChange={e => setShiftForm({...shiftForm, shift_name: e.target.value})}
                  className="w-full border-slate-200 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 shadow-sm"
                  placeholder="e.g., Morning Shift"
                />
              </div>
              
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Start Time</label>
                  <input
                    type="time"
                    required
                    value={shiftForm.start_time}
                    onChange={e => setShiftForm({...shiftForm, start_time: e.target.value})}
                    className="w-full border-slate-200 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 shadow-sm"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">End Time</label>
                  <input
                    type="time"
                    required
                    value={shiftForm.end_time}
                    onChange={e => setShiftForm({...shiftForm, end_time: e.target.value})}
                    className="w-full border-slate-200 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 shadow-sm"
                  />
                </div>
              </div>
              
              <div className="pt-4 flex gap-3 justify-end">
                <button
                  type="button"
                  onClick={() => setIsShiftFormOpen(false)}
                  className="px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-800 hover:bg-slate-100 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-medium hover:bg-indigo-700 shadow-sm transition-colors"
                >
                  Save Shift
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}
